// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.deal(address(c), 10 ether);
        vm.assume(amount <= address(c).balance);
        uint256 balanceBefore = address(c).balance;
        vm.prank(c.owner());
        try c.withdraw(amount) {
            assertTrue(address(c).balance == balanceBefore - amount);
        } catch {
            assertTrue(address(c).balance == balanceBefore);
        }
    }
}
